effect.shader:
#define iTime (loopEvolution + (loopAnimate ? acTime * loopSpeed : 0.0))
#define iResolution vec3(acScreenSize, 1.0)
#define iDate vec4(0.0, 0.0, 0.0, iTime)
#define iMouse vec4(acScreenSize * 0.5, 0.0, 0.0)
void gmGeneratedMainImage( out vec4 f, vec2 g )
{
f.xyz = iResolution;
g += g - f.xy;
g = loopZoom*g/f.y + cos( (atan(g.x, g.y) + iDate.w) *loopArms);
float loopMask=1.0-exp(-loopSpread/g/g).x; f=vec4(mix(loopDark.rgb,loopLight.rgb,loopMask),1.0);
}
void main(){
vec4 gmGenerated=vec4(0.0);
gmGeneratedMainImage(gmGenerated,acScreenNorm*acScreenSize);
vec4 gmSource=texture2DCv(inputImg.texture,acScreenNorm);
float gmAlpha=gmClip?gmSource.a:gmGenerated.a;
vec4 gmResult=vec4(gmGenerated.rgb*gmAlpha,gmAlpha);
gl_FragColor=mix(gmSource,gmResult,gmMix);
gl_FragColor *= texture2DCv(inputImg.texture, acScreenNorm).a;
}
